<script setup>
import { computed, nextTick, ref } from 'vue';

const customers=ref([]),contacts=ref([]),sites=ref([]),companyName=ref(''),canEdit=ref(false),loading=ref(false),search=ref(''),selectedCustomerId=ref('');
const detailDialog=ref(null),customerDialog=ref(null),contactDialog=ref(null),siteDialog=ref(null),customerMode=ref('create'),relationMode=ref('create');
const vatLabels={responsable:'Responsable de IVA',no_responsable:'No responsable de IVA',por_confirmar:'Por confirmar'};
const selectedCustomer=computed(()=>customers.value.find(customer=>customer.id===selectedCustomerId.value)||null);
const selectedContacts=computed(()=>contacts.value.filter(contact=>contact.customerId===selectedCustomerId.value));
const selectedSites=computed(()=>sites.value.filter(site=>site.customerId===selectedCustomerId.value));
const filteredCustomers=computed(()=>{const query=search.value.trim().toLocaleLowerCase('es');return query?customers.value.filter(customer=>[customer.name,customer.identification,customer.email,customer.phone].some(value=>String(value||'').toLocaleLowerCase('es').includes(query))):customers.value;});

function notify(action,extra={}){document.dispatchEvent(new CustomEvent('sigmyp:customer-action',{detail:{action,customerId:selectedCustomerId.value,...extra}}));}
function openDetails(customerId){selectedCustomerId.value=customerId;detailDialog.value?.showModal();}
async function openCustomerEditor(customer=null){selectedCustomerId.value=customer?.id||'';customerMode.value=customer?'edit':'create';customerDialog.value?.showModal();await nextTick();document.querySelector('#customer-form [name="name"]')?.focus();}
async function openContactEditor(contact=null){relationMode.value=contact?'edit':'create';contactDialog.value?.showModal();await nextTick();document.querySelector('#customer-contact-form [name="name"]')?.focus();}
async function openSiteEditor(site=null){relationMode.value=site?'edit':'create';siteDialog.value?.showModal();await nextTick();document.querySelector('#customer-site-form [name="name"]')?.focus();}
function closeAll(){for(const dialog of [detailDialog,customerDialog,contactDialog,siteDialog])if(dialog.value?.open)dialog.value.close();}
function render(payload={}){customers.value=payload.customers||[];contacts.value=payload.contacts||[];sites.value=payload.sites||[];companyName.value=payload.companyName||'';canEdit.value=!!payload.canEdit;loading.value=!!payload.loading;if(selectedCustomerId.value&&!customers.value.some(customer=>customer.id===selectedCustomerId.value))closeAll();window.dispatchEvent(new CustomEvent('sigmyp:workspace-data',{detail:{moduleId:'crm'}}));}
function snapshot(){return {customers:customers.value.map(item=>({...item})),contacts:contacts.value.map(item=>({...item})),sites:sites.value.map(item=>({...item})),companyName:companyName.value,canEdit:canEdit.value,loading:loading.value};}
defineExpose({render,snapshot,openDetails,openCustomerEditor,openContactEditor,openSiteEditor,closeAll,selectedId:()=>selectedCustomerId.value});
</script>

<template>
  <summary>Directorio de clientes</summary>
  <div class="section-head customer-module-head"><div><div class="eyebrow">RELACIONES COMERCIALES</div><h2>Clientes</h2><p class="hint">Administra la ficha, las personas de contacto y las sedes de la compañía activa.</p></div><button id="new-customer" type="button" :hidden="!canEdit" @click="notify('new-customer')">+ Nuevo cliente</button></div>
  <label class="customer-search">Buscar cliente<input v-model="search" type="search" placeholder="Nombre, identificación, correo o teléfono"></label>
  <div id="customer-list" class="table-wrap">
    <table v-if="filteredCustomers.length" class="data-table"><thead><tr><th>Cliente</th><th>Identificación</th><th>Correo</th><th>Teléfono</th><th>Relaciones</th><th>Acciones</th></tr></thead><tbody><tr v-for="customer in filteredCustomers" :key="customer.id"><td><strong>{{customer.name}}</strong></td><td>{{customer.documentType}} {{customer.identification}}</td><td>{{customer.email}}</td><td>{{customer.phone||'—'}}</td><td>{{contacts.filter(item=>item.customerId===customer.id).length}} contactos · {{sites.filter(item=>item.customerId===customer.id).length}} sedes</td><td><div class="row-actions"><button type="button" class="quiet" @click="openDetails(customer.id)">Ver</button><button v-if="canEdit" type="button" class="quiet" @click="notify('edit-customer',{customerId:customer.id})">Editar</button></div></td></tr></tbody></table>
    <p v-else class="empty">{{loading?'Cargando clientes…':search?'No hay clientes que coincidan con la búsqueda.':'Aún no hay clientes registrados para esta empresa.'}}</p>
  </div>

  <dialog ref="detailDialog" class="record-dialog customer-detail-dialog" aria-labelledby="customer-detail-title">
    <div class="section-head"><div><div class="eyebrow">FICHA DEL CLIENTE</div><h2 id="customer-detail-title">{{selectedCustomer?.name||'Cliente'}}</h2><p class="hint">{{companyName}}</p></div><button type="button" class="quiet" @click="detailDialog.close()">Cerrar</button></div>
    <template v-if="selectedCustomer"><dl class="customer-details"><div><dt>Identificación</dt><dd>{{selectedCustomer.documentType}} {{selectedCustomer.identification}}<template v-if="selectedCustomer.documentType==='NIT'">-{{selectedCustomer.dv}}</template></dd></div><div><dt>Correo</dt><dd>{{selectedCustomer.email}}</dd></div><div><dt>Teléfono</dt><dd>{{selectedCustomer.phone||'No registrado'}}</dd></div><div><dt>Dirección principal</dt><dd>{{selectedCustomer.address}}</dd></div><div><dt>Ubicación</dt><dd>{{selectedCustomer.municipality}}, {{selectedCustomer.department}}</dd></div><div><dt>Condición frente al IVA</dt><dd>{{vatLabels[selectedCustomer.vatStatus]||selectedCustomer.vatStatus}}</dd></div><div><dt>Responsabilidades tributarias</dt><dd>{{selectedCustomer.taxResponsibilities}}</dd></div></dl>
      <section class="customer-related-section"><div class="section-head"><div><div class="eyebrow">PERSONAS</div><h3>Contactos</h3></div><button v-if="canEdit" type="button" class="quiet" @click="notify('new-contact')">+ Añadir contacto</button></div><div class="table-wrap"><table v-if="selectedContacts.length" class="data-table"><thead><tr><th>Nombre</th><th>Cargo</th><th>Correo</th><th>Teléfono</th><th>Acciones</th></tr></thead><tbody><tr v-for="contact in selectedContacts" :key="contact.id"><td>{{contact.name}}</td><td>{{contact.jobTitle||'—'}}</td><td>{{contact.email||'—'}}</td><td>{{contact.phone||'—'}}</td><td><button v-if="canEdit" type="button" class="quiet" @click="notify('edit-contact',{relationId:contact.id})">Editar</button></td></tr></tbody></table><p v-else class="empty compact-empty">No hay contactos registrados.</p></div></section>
      <section class="customer-related-section"><div class="section-head"><div><div class="eyebrow">UBICACIONES</div><h3>Sedes</h3></div><button v-if="canEdit" type="button" class="quiet" @click="notify('new-site')">+ Añadir sede</button></div><div class="table-wrap"><table v-if="selectedSites.length" class="data-table"><thead><tr><th>Sede</th><th>Dirección</th><th>Ciudad</th><th>Teléfono</th><th>Acciones</th></tr></thead><tbody><tr v-for="site in selectedSites" :key="site.id"><td>{{site.name}}</td><td>{{site.address}}</td><td>{{site.municipality}}, {{site.department}}</td><td>{{site.phone||'—'}}</td><td><button v-if="canEdit" type="button" class="quiet" @click="notify('edit-site',{relationId:site.id})">Editar</button></td></tr></tbody></table><p v-else class="empty compact-empty">No hay sedes registradas.</p></div></section>
    </template>
  </dialog>

  <dialog ref="customerDialog" class="record-dialog customer-detail-dialog" aria-labelledby="customer-dialog-title"><div class="section-head"><h2 id="customer-dialog-title">{{customerMode==='edit'?'Editar cliente':'Crear cliente'}}</h2><button type="button" class="quiet" @click="customerDialog.close()">Cerrar</button></div><form id="customer-form"><fieldset><div class="two"><label>Nombre completo o razón social<input name="name" maxlength="200" required></label><label>Tipo de documento<select name="documentType"><option value="NIT">NIT</option><option value="CC">Cédula de ciudadanía</option><option value="CE">Cédula de extranjería</option></select></label><label>Número sin puntos ni guiones<input name="identification" pattern="[0-9]{5,15}" required></label><label>Dígito de verificación (solo NIT)<input name="dv" pattern="[0-9]" maxlength="1" required></label><label>Correo electrónico<input name="email" type="email" maxlength="254" required></label><label>Teléfono (opcional)<input name="phone" maxlength="30"></label><label>Dirección principal en Colombia<input name="address" maxlength="250" required></label><label>Departamento<input name="department" maxlength="100" required></label><label>Municipio<input name="municipality" maxlength="100" required></label><label>Condición frente al IVA<select name="vatStatus"><option value="por_confirmar">Por confirmar</option><option value="responsable">Responsable de IVA</option><option value="no_responsable">No responsable de IVA</option></select></label></div><label>Responsabilidades tributarias según RUT<textarea name="taxResponsibilities" rows="2" maxlength="300" required></textarea></label><button type="submit">Guardar cliente</button></fieldset></form><p id="customer-status" role="status"></p></dialog>
  <dialog ref="contactDialog" class="record-dialog customer-detail-dialog" aria-labelledby="contact-dialog-title"><div class="section-head"><h2 id="contact-dialog-title">{{relationMode==='edit'?'Editar contacto':'Añadir contacto'}}</h2><button type="button" class="quiet" @click="contactDialog.close()">Cerrar</button></div><form id="customer-contact-form"><input type="hidden" name="id"><fieldset><div class="two"><label>Nombre completo<input name="name" maxlength="150" required></label><label>Cargo<input name="jobTitle" maxlength="100"></label><label>Correo electrónico<input name="email" type="email" maxlength="254"></label><label>Teléfono<input name="phone" maxlength="30"></label></div><label class="inline-check"><input name="active" type="checkbox" checked> Contacto activo</label><button type="submit">Guardar contacto</button></fieldset></form><p id="customer-contact-status" role="status"></p></dialog>
  <dialog ref="siteDialog" class="record-dialog customer-detail-dialog" aria-labelledby="site-dialog-title"><div class="section-head"><h2 id="site-dialog-title">{{relationMode==='edit'?'Editar sede':'Añadir sede'}}</h2><button type="button" class="quiet" @click="siteDialog.close()">Cerrar</button></div><form id="customer-site-form"><input type="hidden" name="id"><fieldset><div class="two"><label>Nombre de la sede<input name="name" maxlength="150" required></label><label>Teléfono<input name="phone" maxlength="30"></label><label>Dirección<input name="address" maxlength="250" required></label><label>Departamento<input name="department" maxlength="100" required></label><label>Municipio<input name="municipality" maxlength="100" required></label></div><label class="inline-check"><input name="active" type="checkbox" checked> Sede activa</label><button type="submit">Guardar sede</button></fieldset></form><p id="customer-site-status" role="status"></p></dialog>
</template>
